import { Vector2Like } from "../Abstract/Vectors/Vector2Like";
export class Circle {
    center;
    radius;
    static Create(center = Vector2Like.Create(), radius = 1) {
        return new Circle(center, radius);
    }
    static IsPointInsideCircle(point, circle) {
        const dx = point.x - circle.center.x;
        const dy = point.y - circle.center.y;
        const distanceSquared = dx * dx + dy * dy;
        return distanceSquared <= circle.radius * circle.radius;
    }
    static IsSquareInsideCircle(square, circle) {
        const halfSide = square.sideLength / 2;
        const topLeft = {
            x: square.center.x - halfSide,
            y: square.center.y - halfSide,
        };
        const topRight = {
            x: square.center.x + halfSide,
            y: square.center.y - halfSide,
        };
        const bottomLeft = {
            x: square.center.x - halfSide,
            y: square.center.y + halfSide,
        };
        const bottomRight = {
            x: square.center.x + halfSide,
            y: square.center.y + halfSide,
        };
        return (this.IsPointInsideCircle(topLeft, circle) &&
            this.IsPointInsideCircle(topRight, circle) &&
            this.IsPointInsideCircle(bottomLeft, circle) &&
            this.IsPointInsideCircle(bottomRight, circle));
    }
    static IsSquareInsideOrTouchingCircle(square, circle) {
        const halfSide = square.sideLength / 2;
        const topLeft = {
            x: square.center.x - halfSide,
            y: square.center.y - halfSide,
        };
        const topRight = {
            x: square.center.x + halfSide,
            y: square.center.y - halfSide,
        };
        const bottomLeft = {
            x: square.center.x - halfSide,
            y: square.center.y + halfSide,
        };
        const bottomRight = {
            x: square.center.x + halfSide,
            y: square.center.y + halfSide,
        };
        return (this.IsPointInsideCircle(topLeft, circle) ||
            this.IsPointInsideCircle(topRight, circle) ||
            this.IsPointInsideCircle(bottomLeft, circle) ||
            this.IsPointInsideCircle(bottomRight, circle));
    }
    constructor(center = Vector2Like.Create(), radius = 1) {
        this.center = center;
        this.radius = radius;
    }
}
